 m.LEX.update(b.LEX);m.LEX.update(LEX);m.KEYS=sorted(m.LEX,key=len,reverse=True)
 l=next(l for l in json.loads((D/'lessons.2.ja.json').read_text())['lessons']if l['id']=='food-2-025')
